; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpcfw (Amstrad CPC - firmware text and keys), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 1		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs

ntc_start:
			di
			ld (ntc_csp), sp
			ld a, (#BC77)		; Option RomEnable: start the ROMs again
			cp #DF			; AMSDOS has the cassette calls: they are running
			jr z, ntc_roms_on
			ei
			ld de, ntc_free		; the lowest address the ROMs may use (above the arrays)
			ld hl, #ABFF		; the highest (as usual for AMSDOS: it takes about #A700-#ABFF)
			ld c, 7
			call #BCCE		; KL INIT BACK: ROM 7 (DE / HL come back as the new limits)
			di
			ASSERT ntc_free <= #A600, "Option RomEnable: the program and its arrays must end below #A600 (the ROMs take their RAM from #ABFF down)"
ntc_roms_on:
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; main.bas 16: Mode 1
			dw kw_model, 1

			; main.bas 17: Print "AMSDOS test on "; System.Platform
			dw kw_printstrvar, str1
			dw kw_printnl

			; main.bas 18: Print "Devices "; FileSystem.Devices(); " - using "; FileSystem.CurrentDevice()
			dw fn_filesystem_devices, var_filesystem_devices_devices
			dw kw_printstrvar, str2
			dw kw_printstrvar, var_filesystem_devices_devices
			dw fn_filesystem_currentdevice, var_filesystem_currentdevice_currentdevice
			dw kw_printstrvar, str3
			dw kw_printstrvar, var_filesystem_currentdevice_currentdevice
			dw kw_printnl

			; main.bas 19: Print "Volumes "; FileSystem.Volumes(); " - using "; FileSystem.CurrentVolume()
			dw fn_filesystem_volumes, var_filesystem_volumes_volumes
			dw kw_printstrvar, str4
			dw kw_printstrvar, var_filesystem_volumes_volumes
			dw fn_filesystem_currentvolume, var_filesystem_currentvolume_currentvolume
			dw kw_printstrvar, str3
			dw kw_printstrvar, var_filesystem_currentvolume_currentvolume
			dw kw_printnl

			; main.bas 20: Wait
			dw p_wait_c

			; main.bas 22: For i = 0 To 9 : a(i) = 1000 - i * 50 : Next
			dw kw_ztov, var_i
for1_t:
			dw kw_mulvl, var_i, 50, tmp2
			dw kw_sublv, 1000, tmp2, tmp1
			dw kw_aset, arr_a, var_i, tmp1
			dw kw_next1l_n, var_i, 9, for1_t
for1_e:

			; main.bas 23: r = FileSystem.Save("AMS1.DAT", VarPtr(a), 20)
			dw fn_filesystem_save, str5, vp_arr_a, lit_20, var_r

			; main.bas 24: Print "Save AMS1.DAT:"; r
			dw kw_printstrvar, str6
			dw kw_printint, var_r
			dw kw_printnl

			; main.bas 25: r = FileSystem.Load("AMS1.DAT", VarPtr(b), 20)
			dw fn_filesystem_load, str5, vp_arr_b, lit_20, var_r

			; main.bas 26: Print "Load AMS1.DAT:"; r; " -"; b(0); " ..."; b(9)
			dw kw_printstrvar, str7
			dw kw_printint, var_r
			dw kw_printstrvar, str8
			dw kw_printint, arr_b
			dw kw_printstrvar, str9
			dw kw_printint, arr_b+18
			dw kw_printnl

			; main.bas 27: t = Ticks
			dw kw_ticks, tmp0
			dw kw_vtov, tmp0, var_t

			; main.bas 28: Frame : Frame
			dw kw_frame
			dw kw_frame

			; main.bas 29: Print "Ticks still counting:"; IIf(Ticks <> t Or System.TicksPerSecond = 0, " yes", " NO")
			dw kw_ticks, tmp0
			dw kw_cpnevv, tmp0, var_t
			dw kw_ftov, tmp0
			dw kw_goto_ifzero_n, tmp0, ch2_0
			dw kw_strcpy, stmp0, str10
			dw ch2_e_go
ch2_0:
			dw kw_strcpy, stmp0, str11
			dw ch2_e_go
ch2_1:
			dw kw_strcpy, stmp0, str12
ch2_e:
			dw kw_printstrvar, str13
			dw kw_printstrvar, stmp0
			dw kw_printnl

			; main.bas 30: Print "A file that isn't there"
			dw kw_printstrvar, str14
			dw kw_printnl

			; main.bas 31: Print "(AMSDOS may print its message):"
			dw kw_printstrvar, str15
			dw kw_printnl

			; main.bas 32: r = FileSystem.Load("NOFILE.DAT", VarPtr(b), 20)
			dw fn_filesystem_load, str16, vp_arr_b, lit_20, var_r

			; main.bas 33: Print "Load NOFILE.DAT:"; r; " (NotFound is -2)"
			dw kw_printstrvar, str17
			dw kw_printint, var_r
			dw kw_printstrvar, str18
			dw kw_printnl

			; main.bas 34: Wait
			dw p_wait_c

			; main.bas 36: Mode 2
			dw kw_model, 2

			; main.bas 37: Print "Mode 2 (80 columns): saving again..."
			dw kw_printstrvar, str19
			dw kw_printnl

			; main.bas 38: r = FileSystem.Save("AMS2.DAT", VarPtr(a), 20)
			dw fn_filesystem_save, str20, vp_arr_a, lit_20, var_r

			; main.bas 39: Print "Save AMS2.DAT:"; r; " - this line should still be 80 columns, under the one above"
			dw kw_printstrvar, str21
			dw kw_printint, var_r
			dw kw_printstrvar, str22
			dw kw_printnl

			; main.bas 40: Wait
			dw p_wait_c

			; main.bas 42: Mode 1
			dw kw_model, 1

			; main.bas 43: Print "B = try drive B, any other key = skip"
			dw kw_printstrvar, str23
			dw kw_printnl

			; main.bas 44: Do While Inkey <> 0 : Loop
do3_t:
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do3_e
			dw do3_t_go
do3_e:

			; main.bas 45: Do : k = Inkey : Frame : Loop Until k <> 0
do4_t:
			dw kw_inkey, tmp0
			dw kw_vtov, tmp0, var_k
			dw kw_frame
			dw kw_cpnevl, var_k, 0
			dw kw_goto_iffalse_n, do4_t
do4_e:

			; main.bas 46: If k = 66 Or k = 98 Then
			dw kw_cpeqvl, var_k, 66
			dw kw_ftov, tmp0
			dw kw_cpeqvl, var_k, 98
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero_n, tmp0, if5_1

			; main.bas 47: Print "SelectVolume B:"; FileSystem.SelectVolume("B")
			dw fn_filesystem_selectvolume, str24, var_filesystem_selectvolume_selectvolume
			dw kw_printstrvar, str25
			dw kw_printint, var_filesystem_selectvolume_selectvolume
			dw kw_printnl

			; main.bas 48: r = FileSystem.Save("AMS3.DAT", VarPtr(a), 20)
			dw fn_filesystem_save, str26, vp_arr_a, lit_20, var_r

			; main.bas 49: Print "Save B:AMS3.DAT:"; r
			dw kw_printstrvar, str27
			dw kw_printint, var_r
			dw kw_printnl

			; main.bas 50: r = FileSystem.Load("AMS3.DAT", VarPtr(b), 20)
			dw fn_filesystem_load, str26, vp_arr_b, lit_20, var_r

			; main.bas 51: Print "Load:"; r; " -"; b(0)
			dw kw_printstrvar, str28
			dw kw_printint, var_r
			dw kw_printstrvar, str8
			dw kw_printint, arr_b
			dw kw_printnl

			; main.bas 52: r = FileSystem.SelectVolume("A")
			dw fn_filesystem_selectvolume, str29, var_r

			; main.bas 53: Print "Volumes now "; FileSystem.Volumes()
			dw fn_filesystem_volumes, var_filesystem_volumes_volumes
			dw kw_printstrvar, str30
			dw kw_printstrvar, var_filesystem_volumes_volumes
			dw kw_printnl

			; main.bas 54: End If
if5_1:

			; main.bas 55: Print "done"
			dw kw_printstrvar, str31
			dw kw_printnl

			; main.bas 56: Wait
			dw p_wait_c

			; main.bas 57: End
			dw kw_stop

; ============================================================
; sub wait (normal mode)
; ============================================================

p_wait:

			; main.bas 60: Print "Press a key"
			dw kw_printstrvar, str32
			dw kw_printnl

			; main.bas 61: Do While Inkey <> 0 : Loop
do6_t:
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do6_e
			dw do6_t_go
do6_e:

			; main.bas 62: Do : Frame : Loop Until Inkey <> 0
do7_t:
			dw kw_frame
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do7_t
do7_e:
			dw p_wait_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

ch2_e_go:			ld sp, ch2_e
			jp ntc_xn
do3_t_go:			ld sp, do3_t
			jp ntc_xn
do6_t_go:			ld sp, do6_t
			jp ntc_xn

p_wait_c:		; call wait (normal)
			ld (p_wait_rs), sp
			ld sp, p_wait
			jp ntc_xn
p_wait_r:		; end of wait
			ld sp, (p_wait_rs)
			jp ntc_xn

; ============================================================
; Inline assembly (#asm ... #endasm)
; ============================================================

fn_filesystem_load:		; function load (asm keyword), FileSystem.cls line 56
            pop hl		; FileSystem.cls 57
            ld (fs_a1), hl		; FileSystem.cls 58
            pop hl		; FileSystem.cls 59
            ld e, (hl)		; FileSystem.cls 60
            inc hl		; FileSystem.cls 61
            ld d, (hl)		; FileSystem.cls 62
            ld (fs_a2), de		; FileSystem.cls 63
            pop hl		; FileSystem.cls 64
            ld e, (hl)		; FileSystem.cls 65
            inc hl		; FileSystem.cls 66
            ld d, (hl)		; FileSystem.cls 67
            ld (fs_a3), de		; FileSystem.cls 68
            pop hl		; FileSystem.cls 69
            ld (fs_res), hl		; FileSystem.cls 70
            ld hl, fs_load		; FileSystem.cls 71
            jp fs_go		; FileSystem.cls 72
			ret			; end of #asm

fn_filesystem_save:		; function save (asm keyword), FileSystem.cls line 78
            pop hl		; FileSystem.cls 79
            ld (fs_a1), hl		; FileSystem.cls 80
            pop hl		; FileSystem.cls 81
            ld e, (hl)		; FileSystem.cls 82
            inc hl		; FileSystem.cls 83
            ld d, (hl)		; FileSystem.cls 84
            ld (fs_a2), de		; FileSystem.cls 85
            pop hl		; FileSystem.cls 86
            ld e, (hl)		; FileSystem.cls 87
            inc hl		; FileSystem.cls 88
            ld d, (hl)		; FileSystem.cls 89
            ld (fs_a3), de		; FileSystem.cls 90
            pop hl		; FileSystem.cls 91
            ld (fs_res), hl		; FileSystem.cls 92
            ld hl, fs_save		; FileSystem.cls 93
            jp fs_go		; FileSystem.cls 94
			ret			; end of #asm

fn_filesystem_devices:		; function devices (asm keyword), FileSystem.cls line 158
            pop hl		; FileSystem.cls 159
            ld (fs_res), hl		; FileSystem.cls 160
            ld hl, fs_devices		; FileSystem.cls 161
            jp fs_go0		; FileSystem.cls 162
			ret			; end of #asm

fn_filesystem_currentdevice:		; function currentdevice (asm keyword), FileSystem.cls line 168
            pop hl		; FileSystem.cls 169
            ld (fs_res), hl		; FileSystem.cls 170
            ld hl, fs_curdev		; FileSystem.cls 171
            jp fs_go0		; FileSystem.cls 172
			ret			; end of #asm

fn_filesystem_volumes:		; function volumes (asm keyword), FileSystem.cls line 191
            pop hl		; FileSystem.cls 192
            ld (fs_res), hl		; FileSystem.cls 193
            ld hl, fs_volumes		; FileSystem.cls 194
            jp fs_go0		; FileSystem.cls 195
			ret			; end of #asm

fn_filesystem_currentvolume:		; function currentvolume (asm keyword), FileSystem.cls line 201
            pop hl		; FileSystem.cls 202
            ld (fs_res), hl		; FileSystem.cls 203
            ld hl, fs_curvol		; FileSystem.cls 204
            jp fs_go0		; FileSystem.cls 205
			ret			; end of #asm

fn_filesystem_selectvolume:		; function selectvolume (asm keyword), FileSystem.cls line 211
            pop hl		; FileSystem.cls 212
            ld (fs_a1), hl		; FileSystem.cls 213
            pop hl		; FileSystem.cls 214
